/* 纪实修订：只陈述所列资料能够支持的事件，不补写对白和心理活动。 */
(() => {
const revisions = {
'the-ship': ['罗德岛的组织背景与行动','罗德岛以矿石病研究和感染者援助为主要工作，同时设有医疗、工程与武装行动部门。阿米娅担任公开领导人，凯尔希参与医疗与组织管理，博士在切尔诺伯格获救后重新参与指挥。',[
 ['组织与人员','罗德岛接收来自不同国家和组织的成员，其中既有感染者，也有非感染者。其工作包括治疗、安置、外勤和与地方势力协商。能够提供医疗，并不意味着它有能力直接改变所在国家对感染者的政策。','主线第一部中，罗德岛先在切尔诺伯格营救博士，随后介入龙门与整合运动的冲突。博士的失忆使其难以说明过去的经历，现阶段的关系主要通过实际指挥和共同作战重新建立。'],
 ['行动中的分歧','冲突双方都有感染者。罗德岛试图救助感染者，但也会阻止针对平民与城市的暴力行为。第六章中，煌在交战前要求整合运动成员投降，并说明可以将其带离当前冲突。','阿米娅参与指挥、交涉和战斗，也面对无法救回的人。凯尔希掌握更多历史信息，但在许多场合只公开与当下行动有关的部分。这一信息差是阅读罗德岛早期故事时需要保留的背景。'],
 ['与巴别塔的联系','《巴别塔》补充了这艘陆行舰、特蕾西娅、凯尔希、博士与阿米娅之间的旧日关系。巴别塔原有事业的结束，并未使其人员和遗留问题一同消失。罗德岛后来继续开展的工作，既继承了部分目标，也面对新的条件。']
 ]],
'children-of-winter': ['乌萨斯学生自治团的灾后生活','《乌萨斯的孩子们》记录了凛冬、早露、古米等人在切尔诺伯格事件后的生活。她们离开灾区并进入罗德岛，但事件中的经历仍持续影响饮食、睡眠、人际关系与日常反应。',[
 ['事件背景','切尔诺伯格的混乱波及学校，学生原有的生活秩序遭到破坏。家世与同学关系在危机中产生新的影响，食物、安全和相互信任成为直接问题。各人的遭遇并不相同，不能以单一经历概括整个自治团。','凛冬在同伴中承担带头和保护的职责。早露的贵族出身使其处境和部分同学不同，真理较多通过观察与思考理解环境，古米则在生活习惯中保留了灾难的影响。'],
 ['抵达罗德岛之后','罗德岛提供了相对安全的居住、治疗与工作条件。故事以厨房、宿舍、训练和闲谈等场景呈现她们的状态，而不是只回顾灾难本身。离开危险地点，并未让所有人立即恢复。','自治团成员继续共同生活，也会发生争执、玩笑和互相照顾。关系的维持帮助她们重新建立日常，但作品没有把这种支持写成能够一次消除所有创伤的办法。'],
 ['本篇的收束','故事保留了继续生活和长大的可能，没有为每个人的心理状态给出统一终点。阅读时应分别对待已明确发生的事件、人物的自述，以及读者对其行为的解释。']
 ]],
'lungmen-lights': ['龙门事变中的近卫局与市民','龙门是主线第一部的重要地点。陈、星熊与诗怀雅在近卫局工作，魏彦吾负责城市治理；企鹅物流等组织则从另一角度呈现城内商业、街区与人员往来。',[
 ['近卫局的行动','整合运动进入龙门后，近卫局与罗德岛合作应对城市危机。陈既承担指挥与作战职责，也因塔露拉的身份与个人关系持续追查事件。公职责任、感染者处境和私人历史在这一阶段发生交叉。','星熊与诗怀雅参与城市防务和近卫局事务。她们与陈有分歧，但仍在同一套工作中协作。陈后来的离开，也意味着其他成员需要继续处理留在城中的职责。'],
 ['街区与企鹅物流','《喧闹法则》围绕企鹅物流及进入龙门的叙拉古人员展开。德克萨斯、能天使等人的行动展示了近卫局之外的城市生活，包括物流业务、酒吧、人情网络与街区冲突。','这条支线的叙事节奏较为轻快，与主线战事并非同一场事件。将两者并读可以补充龙门的社会面貌，但不能据企鹅物流的日常推定全体市民的生活条件。'],
 ['陈的后续选择','龙门事变后，陈离开原有岗位并继续参与其他地区的行动。星熊和诗怀雅仍与城市保持联系。本卷在此记录其道路发生变化的阶段，不把离职视为陈全部经历的结局。']
 ]],
'yan-human-world': ['岁相关事件中的地方人物','《画中人》《将进酒》《登临意》分别以画中世界、尚蜀和玉门等地点展开，涉及夕、令、重岳等岁片段，也包含地方官员、镖局、守军与普通居民的行动。',[
 ['画中世界','《画中人》中，炎熔、乌有和嵯峨等人进入与夕有关的画中世界。画中居民的生活、来访者的行动和夕对外界的态度共同构成冲突。年与夕的交谈则补充了岁片段之间的关系。','年较多参与外界事务，夕长期与外界保持距离。两人的不同做法是剧情已经呈现的性格差异，但不能据此推出所有岁片段均持相同立场。'],
 ['尚蜀与玉门','《将进酒》围绕尚蜀的酒盏、镖局旧事和多方争夺展开。老鲤受委托进入事件，令也与局势相关。郑清钺、杜遥夜等地方人物各有旧事与事务，不能只视作古老存在计划中的附属角色。','《登临意》将叙事转向玉门。重岳长期驻留于此，参与武学传承与守城事务；仇白、林雨霞等人的行程和行动，也分别与个人经历和城内局势有关。'],
 ['资料时点','这几篇包含回忆、当下事件与尚未解释的计划。本文按作品分别记录，不将出现顺序直接当作世界内年代顺序，也不对岁的完整起源和最终计划作补写。']
 ]],
'the-grain': ['大荒城的农业试验与人员行动','《怀黍离》以大荒城的农业试验和相关事务为中心。黍长期参与种植与研究，左乐在此接触实际劳动，地方官员、天师与职农则承担各自工作。',[
 ['试验的条件','农业试验涉及种子、土地、气候、设施和人员协作。黍的能力与经验是其中一部分，但剧情没有把粮食生产简化为可以由某个人独立完成的任务。试验还受到行政、资源与地方关系的影响。','左乐在执行司岁台相关职责的同时进入田间劳动。他接触到卷宗之外的实际条件，也需要重新理解黍与职农之间的关系。其职责并未因此取消，但判断所依据的信息有所增加。'],
 ['参与者与利益','宁辞秋等官员、各类天师和职农参与事件。不同群体对于技术、收成与资源有不同需求，因此试验能否推进，既取决于技术结果，也取决于组织与协作。','年迈商人的经历引出对利益和共赢的讨论。这一部分以人物见闻与对话呈现，不应直接当作炎的完整经济制度说明。'],
 ['结果与范围','故事围绕试验、劳动与人的生活展开。本文记录这一活动中的关系和行动，不将一次试验的进展等同于整个国家粮食问题已得到解决。']
 ]],
'victoria-fire': ['塔拉冲突与伦蒂尼姆局势','主线第九章从小丘郡等地展开，随后转向伦蒂尼姆。风笛、号角与苇草等人的经历，分别涉及军队行动、塔拉身份和地方居民在战乱中的处境。',[
 ['地方行动','风笛与号角原本按军队职责执行任务，随后发现当地冲突涉及更复杂的军事和政治安排。行动造成伤亡与人员失散，促使幸存者继续追查同伴和相关责任。','苇草因德拉克身份被赋予政治意义，并曾被纳入深池的行动。她在这一阶段并非始终能够自主决定身份和力量的用途，与罗德岛接触后才逐渐取得新的行动空间。'],
 ['苇草与流离者','《照我以火》集中记录苇草与流亡群体的同行。她需要处理追索、伤亡和自身能力带来的后果，并在具体事件中选择如何帮助眼前的人。本文不以未被明确说明的心理活动代替这些行动。','伦蒂尼姆的抵抗则涉及自救军、工厂人员和普通居民。国家层面的争夺进入街区和地下通道后，转化为通行、补给、救援与撤离等实际问题。'],
 ['人物与身份','推进之王的王室身份与格拉斯哥帮的共同生活相互关联，风笛继续追寻同伴与真相。本文止于所列主线阶段及《照我以火》，不概括后续伦蒂尼姆战局和王权结果。']
 ]],
'kazdel-home': ['卡兹戴尔佣兵与巴别塔','《生于黑夜》以W、赫德雷和伊内丝等佣兵的经历呈现卡兹戴尔战事，《巴别塔》则补充特蕾西娅及相关人员的组织活动和旧日关系。',[
 ['佣兵时期','W在战地接过一名死者留下的代号，随后与赫德雷、伊内丝共同活动。佣兵接受委托、判断风险并维持队伍，战争因而既是政治冲突，也是这些人的生存条件。','三人与巴别塔发生联系后，原有雇佣关系受到新的目标和人际关系影响。特蕾西娅对萨卡兹未来的设想，使部分参与者开始接触不同于持续作战的生活方案。'],
 ['组织与内战','巴别塔在卡兹戴尔内战中开展行动。特蕾西娅与特雷西斯对未来采用不同道路，博士、凯尔希和阿米娅也各自处于这一历史过程之中。各方掌握的信息和承担的责任并不相同。','W后来继续受到与特蕾西娅相关的记忆影响。其行动中包含追查、试探和报复等不同因素，不能仅以某一种情绪概括全部经历。'],
 ['后续与资料边界','巴别塔结束后，相关人员继续在其他地点活动，旧日关系亦未随之终止。本文不把萨卡兹王庭、佣兵与普通居民视为同一立场，也不将后续主线中尚未在本篇展开的结果提前写入。']
 ]],
'nearl-light': ['骑士竞技与临光家族的行动','《玛莉娅·临光》《红松林》《长夜临光》从临光家族、感染者骑士与竞技制度等角度呈现卡西米尔。比赛与商业合同、媒体传播和场外暴力相互关联。',[
 ['玛莉娅参赛','玛莉娅为维持家族的骑士地位进入竞技场。她原本熟悉机械工作，作战经验有限，参赛后需要面对赞助、对手和比赛规则。个人成绩因此不仅涉及荣誉，也会影响家族的现实处境。','红松林成员则以感染者骑士的身份行动。她们需要处理参赛资格、治疗、生存与同伴安全等问题，其处境与受到广泛关注的骑士并不相同。'],
 ['玛嘉烈归来','玛嘉烈返回大骑士领，参与竞技并公开坚持自身的骑士原则。她与血骑士、薇薇安娜等人的交锋，产生了比赛胜负之外的公共影响。商业联合会、无胄盟等组织亦持续介入局势。','玛恩纳的经历呈现临光家族的另一条路线。他对现实的态度与玛嘉烈不同，仍会在具体事件中采取行动。家族内部并没有完全一致的应对方式。'],
 ['比赛之后','活动结尾保留感染者骑士与其他人员继续合作的情况，并未宣布竞技制度中的问题全部消失。本文区分个人比赛结果与社会结构的变化，不将一次胜利写成最终改革完成。']
 ]],
'kjerag-snow': ['谢拉格事变与圣女的政治行动','《风雪过境》中，博士受邀前往谢拉格，并介入喀兰贸易、三族议会与蔓珠院之间的冲突。银灰推动对外开放，恩雅则以圣女身份参与关键决定。',[
 ['事变的背景','喀兰贸易引入技术与商品，改变了谢拉格原有的经济和权力关系。银灰认为国家需要应对外部环境，为此制定计划；灵知在计划中承担技术和政治任务，也承受其个人代价。','布朗陶与佩尔罗契家族分别维护自身利益，蔓珠院掌握宗教与传统解释权。各方并非只因个人好恶行动，制度位置与家族关系同样影响判断。'],
 ['博士与恩雅介入','博士在事变中调整局势，未完全沿银灰原定安排推进。恩雅也不再只接受家族和长老对圣女角色的安排，而是在关键阶段以自己的宗教权威公开发言。','这一行动使她获得更明确的政治位置，但并未直接消除与银灰之间的矛盾。恩希亚继续关心兄姐关系，显示家族层面仍有尚未解决的后续问题。'],
 ['后续作品','《银心湖列车》继续呈现开放后的外交、旅游与外部势力介入。本文主体止于《风雪过境》，将该活动列为后续阅读，不把两次事件混作同一场事变。']
 ]],
'columbia-stars': ['莱茵生命的研究争议与升空计划','《绿野幻梦》《孤星》记录了莱茵生命研究引发的争议，以及克丽斯腾推进升空计划的过程。赫默、塞雷娅、缪尔赛思、军方与梅兰德等各自参与其中。',[
 ['研究与责任','莱茵生命的工作与哥伦比亚的资本、军方需求存在联系。部分实验使研究目标与参与者的安全发生冲突，赫默和塞雷娅因相关事件产生分歧，并继续承担对伊芙利特的照顾。','《绿野幻梦》将实验参与者的处境进一步推到前景。赫默的关注逐渐从保护个别人，扩展为研究组织如何对后果负责；这也是理解她后来行动的重要背景。'],
 ['克丽斯腾的计划','《孤星》中，克丽斯腾加速实施升空计划，多方机构试图介入或控制结果。她对于天空的研究与父母的经历有关，但具体行动也包含对组织资源、人员和外部力量的使用。','计划最终突破了泰拉天空的屏障，使既有世界认知发生变化。博士与凯尔希接触保存者相关设施和信息，也获得有关遥远过去的材料。这些发现与此前实验造成的伤害属于不同层面的事实。'],
 ['留在地面的人员','事件后，赫默继续面对研究伦理和组织责任，缪尔赛思也作出与归属有关的个人选择。本文不以科学突破替所有参与者作统一评价，分别记录成果、代价和后续责任。']
 ]],
'siracusa-roads': ['德克萨斯返乡与新沃尔西尼计划','《叙拉古人》记录德克萨斯返回叙拉古后卷入家族冲突，以及莱昂图索等人围绕新沃尔西尼展开的行动。拉普兰德、西西里夫人与狼主也参与局势。',[
 ['旧有家族关系','德克萨斯在龙门已有新的工作和伙伴，返乡后仍需面对过去形成的关系与行动习惯。她理解当地家族的威胁方式，但不愿继续按这些规则生活。','拉普兰德同样受到过去影响，对德克萨斯和叙拉古秩序采取不同做法。两人并非因为共享经历就具有一致目标，作品持续保留了她们的差异。'],
 ['新城的安排','莱昂图索试图推动不再完全依靠旧家族规则的城市生活。斥罪的法律实践则暴露出规则与现实权力之间的距离。贝纳尔多等父辈人物的安排，也影响着新城与年轻人的道路。','西西里夫人及狼主仍然介入叙拉古事务，新城并非在没有旧势力的条件下建立。因此，家族冲突的结束与新秩序能否持续运作，应作为两个问题分别观察。'],
 ['本篇时点','德克萨斯继续选择与龙门伙伴相连的生活，拉普兰德则走向另一条道路。本文止于《叙拉古人》，不概括后续《挽歌燃烧殆尽》的发展。']
 ]],
'leithanien-music': ['黑键、白垩与巫王遗留计划','《尘影余音》围绕黑键和白垩的相遇展开。两人各自的身份、矿石病相关处境与音乐活动，最终受到巫王遗留计划的影响。',[
 ['两人的处境','黑键具有贵族背景，并与巫王相关的旧日安排存在联系。这一身份并未使其能够自由决定未来。白垩是感染者，需要照顾亲人，也希望继续演奏与生活。','二人通过音乐和共同经历建立友谊。车尔尼参与其中，以自己的经验和要求影响他们。音乐在这些场景中既是专业活动，也是一种建立关系的方式。'],
 ['事件经过','与巫王有关的研究和计划仍在影响后来的人。黑键与白垩被卷入其中，个人身体与能力受到利用。旧统治者已经离开公开政治舞台，并不等于相关技术和追随者全部消失。','白垩最终死亡，黑键则在事件后继续生活，并面对与过去的联系。本文将这一结果明确列为剧情事实，不以想象中的对白或心理独白补写两人的告别。'],
 ['延伸阅读','《崔林特尔梅之金》继续展开莱塔尼亚的权力与艺术问题。它可以补充地区背景，但不改变白垩在《尘影余音》中已有的人生经历与结局。']
 ]],
'laterano-bells': ['万国峰会期间的拉特兰事件','《吾导先路》以万国峰会期间发生的冲突为中心，将安多恩与昔日同伴的往事、拉特兰律法，以及塞茜莉亚的身份问题联系起来。',[
 ['旧行动与分歧','安多恩、莫斯提马、蕾缪安和菲亚梅塔曾共同执行任务，后来因事件产生分离与不同判断。菲亚梅塔是黎博利，不能像萨科塔成员那样依赖共感理解彼此，因此旧事中的情绪与责任也不能只用共感解释。','安多恩在拉特兰之外见过不同群体的处境，并据此质疑圣城庇护的边界。其信仰和行动与这些经历有关，但他的判断并不代表所有萨科塔人的共同立场。'],
 ['塞茜莉亚的身份','塞茜莉亚的身世涉及萨科塔与萨卡兹的关系。母亲去世后，艾泽尔试图帮助她完成告别、获得身份并继续生活，使原本抽象的规则争议进入一个孩子的实际处境。','安多恩与教宗相遇，则将讨论推向律法、信仰和共同体的未来。双方交换观点，但作品并未写成长期边界在一次对话中全部消失。'],
 ['事件之后','塞茜莉亚与艾泽尔离开圣城，菲亚梅塔等人仍需处理旧事留下的关系。《空想花庭》可继续补充拉特兰体系边缘群体的处境，本文不提前复述该篇全部结果。']
 ]],
'iberia-lighthouse': ['格兰法洛、灯塔与愚人号事件','《覆潮之下》《愚人号》分别从盐风城、格兰法洛及海上巨舰展开，记录海岸居民、审判庭、深海教会与深海猎人在海嗣威胁下的行动。',[
 ['海岸背景','盐风城居民长期生活在灾难留下的影响中。审判庭和深海教会分别以不同方式介入当地，斯卡蒂的到来使隐藏的问题进一步显露。海岸居民并非此前没有行动，而是在有限条件下维持生活。','《愚人号》中，事件转向格兰法洛、灯塔与失落的巨舰。艾丽妮依照审判官训练参与行动，达里奥提供经验并承担职责；深海猎人则带来不同的知识和作战能力。'],
 ['乔迪的参与','乔迪没有猎人的身体能力，主要通过对灯塔、医疗和地方情况的了解参与危机处理。他的行动与蒂亚戈及当地生活相连，不能以战斗能力强弱衡量其在事件中的作用。','愚人号上的阿方索与加西亚保留着伊比利亚旧舰队的经历。与猎人的相遇使黄金时代的遗留力量再次面对现实威胁，也暴露不同参与者在知识和判断上的限制。'],
 ['事件之后','乔迪后来以流明为代号继续活动，艾丽妮则在失去与职责变化后继续前进。本文采用活动主叙事，不将深海题材集成战略的全部分支并入这条经历。']
 ]],
'aegir-depth': ['深海猎人与阿戈尔的相关行动','《覆潮之下》《愚人号》《生路》逐步展开深海猎人、海嗣与阿戈尔之间的关系。斯卡蒂、幽灵鲨、歌蕾蒂娅和乌尔比安在不同阶段参与行动。',[
 ['猎人的状况','深海猎人具有特殊的身体能力，其来源和变化也带来风险。斯卡蒂较多独自行动，幽灵鲨经历记忆与精神状态的变化，歌蕾蒂娅则承担维持队伍和实施计划的职责。','这些差异影响各人与陆上机构、海洋及同伴的关系。《覆潮之下》使海嗣和深海教会进入更多人的视野，《愚人号》进一步补充猎人与海洋之间的联系。'],
 ['返回深海的线索','《生路》将乌尔比安与阿戈尔城市推到前景。阿戈尔拥有自己的技术、社会秩序和应对方式，但面对海嗣时同样存在信息不足、判断分歧和实际风险。','乌尔比安根据自身经验调查并采取行动。他既需要应对海洋中的威胁，也需要审视本方的做法。此阶段的合作和分歧，应依据具体事件分别记录。'],
 ['概念与范围','海嗣、深海教会、阿戈尔及深海猎人是相关但不同的概念，不能互相替代。本文止于所列活动，不补写后续深海故事，也不把分支结局作为所有人物的固定未来。']
 ]],
'sargon-roads': ['萨尔贡的沙漠与密林两条记录','《遗尘漫步》通过不同时地的事件补充凯尔希与异客的经历，《密林悍将归来》则记录嘉维尔返回故乡后的行动。两篇发生的地方社会和条件并不相同。',[
 ['凯尔希与艾利奥特','年轻的艾利奥特失去导师后，被卷入研究、地方权力和复仇相关事件。凯尔希参与其中，后来也在其他时期与相关人员发生联系。异客的履历需要连同这段早期经历阅读。','《遗尘漫步》同时包含萨尔贡以外的地点，不能将所有段落都视为同一时期的萨尔贡地方史。回忆出现的先后，也不等于事件发生的先后。'],
 ['嘉维尔返回密林','《密林悍将归来》中，嘉维尔回到熟悉的部族环境，接触祖玛玛的机械活动和地方竞争。她保留直接处理冲突的行动方式，同时坚持自己作为医生的工作。','祖玛玛对机械的兴趣与部族生活相连，外来技术和人员又继续影响其发展。故事呈现的是具体聚落与人物，不能据此概括整个萨尔贡的制度和生活方式。'],
 ['并读的限制','萨尔贡地域广阔，不同地区的政治、技术和日常生活存在差异。本文将两条故事并列，目的在于保留这种差异，而非把黄沙与密林拼成单一社会图景。']
 ]],
'bolivar-holiday': ['多索雷斯赛事与政治危机','《多索雷斯假日》记录陈与林雨霞参加当地赛事期间发生的事件。坎黛拉经营城市秩序，潘乔的行动则将玻利瓦尔长期冲突带入旅游与商业活动。',[
 ['城市与赛事','多索雷斯通过旅游、比赛和商业宣传吸引人员与资源。坎黛拉依靠利益协调和政治判断维持运作，这种繁荣具有明确的管理安排，并不代表整个玻利瓦尔拥有相同生活条件。','陈与林雨霞以不同经验参与赛事。她们熟悉龙门，却在当地面对另一套城市运作方式。同行中的分歧既与个人关系有关，也涉及如何理解秩序和实际利益。'],
 ['危机发生','潘乔基于自身经历和政治判断采取行动，使度假城市受到直接冲击。埃内斯托与父亲的关系，使这场冲突同时涉及家庭、继承和个人选择。','事件处理过程中，城市各方继续围绕安全、控制与利益行动。比赛的轻松外观未取消政治背景，也不能作为判断所有参与者立场的唯一依据。'],
 ['陈的后续行程','陈在这次旅行后继续前行，与龙门和同伴的关系并未完全切断。本文只记录《多索雷斯假日》的阶段，不将后续《丛林症结》纳入同一场事件。']
 ]],
'siesta-summer': ['黑曜石节期间的汐斯塔危机','《火蓝之心》以汐斯塔黑曜石节为背景，记录锡兰对火山相关问题的调查、黑的保护行动，以及城市管理者对风险与未来安排的处理。',[
 ['节庆与调查','音乐节吸引罗德岛及其他来客。锡兰关心家乡的实际危险，并试图使自己的研究进入城市决策。调查因此不仅涉及自然现象，也受到行政与商业安排的影响。','黑长期承担保护锡兰的职责。两人关系紧密，但锡兰也逐渐要求参与判断和行动，双方需要在保护与自主之间调整相处方式。'],
 ['城市面临的选择','火山威胁迫使城市正面处理未来的生存条件。赫尔曼作为管理者，需要兼顾居民生活、既有繁荣与风险。有关城市变化的安排，应与宣传中呈现的度假景象分别理解。'],
 ['后续时点','《火山旅梦》可继续补充汐斯塔变化后的生活。本文不把后续结果提前写入《火蓝之心》，也不以现实地理和火山知识补全作品未说明的设定。']
 ]],
'sami-watch': ['萨米旅行中的向导与守望者','《眠于树影之中》记录北地旅行者与提丰、寒檀等人的相遇。路线判断、环境变化和地方经验共同影响行程，森林与冰原并非无人生活的空白区域。',[
 ['向导的经验','提丰根据长期在北地生活和行动的经验辨认危险，并为同行者提供指引。她的判断涉及具体环境，而不只是地图上的方向。外来者需要了解这些经验的适用条件。','寒檀与森林、预示和地方职责相连。她接触到的警示涉及土地受到的侵蚀，也影响其后续行程。本文只记录活动明确呈现的行动，不自行解释所有现象的机制。'],
 ['外来知识与地方实践','旅途中出现不同知识方式的接触。外来人员带着研究和探索目的，向导则更熟悉道路与生存条件。协作需要双方承认各自掌握的信息并不完整。'],
 ['阅读范围','《探索者的银凇止境》可以继续补充北方环境和探索活动，但该玩法含有分支。本文不把全部探索结果串成一段固定历史，也不根据玩法推导未说明的邪魔规则。']
 ]],
'durin-city': ['杜林聚居地的工程与迁徙','《理想城：长夏狂欢季》记录嘉维尔、祖玛玛、可颂等人进入杜林聚居地后的经历。至简参与工程相关事务，城市居民则面对基础设施与居住条件的变化。',[
 ['聚居地的生活','地下聚居地拥有湖水、娱乐设施、机械技术和自己的工作节奏。外来者进入后，既参与日常活动，也与居民在技术和事务处理上发生接触。不能仅从轻快的叙事表面判断当地没有组织和责任。','至简重视建造和专业认可，事件推进后，他需要把设计与实际居民的需求联系起来。工程不再只是个人作品，也涉及公共设施如何使用、由谁维护。'],
 ['迁徙与协作','当原有城市面临必须改变的条件，居民需要处理迁徙、资源和重建问题。嘉维尔等人在其中采取行动，但城市的后续生活仍依靠居民自身持续参与。'],
 ['单位与概念','杜林是族群称谓，不同地下聚居地不能直接视为一个统一国家。本文按活动中的具体城市记录，不将其制度和生活方式推及所有杜林人。']
 ]],
'rim-departure': ['阿米娅档案中的雷姆必拓背景','阿米娅基础档案记录其出身地为雷姆必拓。《巴别塔》的相关回忆补充了她年幼时与旧日人员的关系。现有材料可用于说明个人来路，不能据此重建整个地区的历史。',[
 ['能够确认的材料','阿米娅后来担任罗德岛公开领导人，在更早的回忆中则仍是需要照顾的孩子。她与博士、凯尔希、特蕾西娅等人的接触，是理解其后续经历的重要部分。','基础档案中的出身地，与后续任职和行动地点是不同信息。人物后来在多个国家活动，并不意味着原有来路被取消，也不能反过来以其领导者身份解释所有童年经历。'],
 ['地区记录的限度','雷姆必拓常与矿业联系在一起，但本篇所用的个人材料不足以构成完整产业史或社会全景。关于具体矿区、家庭生活和早期行程的未明确细节，本文均不补写。'],
 ['后续阅读','《巴别塔》可与阿米娅的正式档案并读。本文未概括后续《挽歌燃烧殆尽》中的地区发展，因此保留为资料范围明确的档案短篇。']
 ]],
'higashi-blade': ['露华村任务与夜刀、黑角的变化','《落叶逐火》记录夜刀、黑角在东国露华村遭遇的事件。两人在任务后获得新装备并返回罗德岛，相关档案也记述了其工作方式与日常行为的变化。',[
 ['原有岗位','夜刀长期担任罗德岛行动组成员与组长，黑角参与前线保护和舰内工作。两人的可靠性主要通过持续执行任务和与同伴协作呈现，早期档案并未完整公开其全部过去。','露华村任务出现陌生威胁，也涉及当地居民的处境。两人需要在完成任务之外判断行动结果，并处理保护他人与自身安全之间的取舍。'],
 ['返回之后','夜刀获得新装备后承担更高难度的行动。档案记述她试图减少代价、争取更完整的任务结果，同时仍在适应新的判断方式。其感染程度变化也接受医疗部检查与治疗。','黑角则增加知识储备，更主动表达自己的观点。档案将这些改变与露华村的经历联系起来，但对两人私人关系保留了一定距离。'],
 ['资料边界','本文不将流言视作已经确认的关系结论，不用一个村庄代表整个东国，也不把联动事件中的其他世界设定直接当作泰拉的一般规律。']
 ]],
'minos-heroes': ['帕拉斯的离乡与刻俄柏的命名','帕拉斯的档案提供了一个观察米诺斯英雄传统与个人处境的窗口。《午间逸话·流浪者的归宿》则记录刻俄柏试图辨认斧上铭文、却未能抵达米诺斯的经历。',[
 ['帕拉斯的经历','帕拉斯曾担任米诺斯祭司，感染矿石病后离开原有生活。她仍重视英雄传统和荣誉，但公开身份与实际处境已经发生变化。其后在萨尔贡的经历和与一位萨卡兹护卫的同行，也被档案记录。','这些材料既涉及地方传统，也涉及治疗、照顾和日常关系。本文不因其失去原有名望，就把之后的人生仅写为早期身份的附属。'],
 ['刻俄柏的行程','刻俄柏出身玻利瓦尔，原本希望前往米诺斯辨认斧上的铭文。她在漫游中走错方向，始终没有抵达，后来在莱塔尼亚获救。火神读出铭文，使她获得了“刻俄柏”这个名字。'],
 ['并读的理由与限制','两人的故事可围绕米诺斯的名字、传统与远行并读，但她们并非同一出身地，也没有共享同一条行程。本篇采用早期档案，不概括后续米诺斯活动和完整地区编年。']
 ]]
};
for(const s of window.TERRA.stories){const r=revisions[s.id];if(!r)throw Error('Missing documentary revision: '+s.id);s.title=r[0];s.intro=r[1];s.sections=r[2];s.reflection='本篇按上方所列作品与档案时点整理。事件陈述与资料范围以正文和出处为准；跨地区主题并读属于编写安排，不代表各事件具有直接因果关系。';}
window.TERRA.writingStyle='纪实叙述：背景、事件、行动与后续；不补写对白和心理活动。';
})();
